public record Envelope(Order Body, IReadOnlyList<Func<Order, Task<Order>>> Slip, int Cursor = 0);

var envelope = new Envelope(order, new[] { Validate, Reserve, Charge });
while (envelope.Cursor < envelope.Slip.Count)
{
    var step = envelope.Slip[envelope.Cursor];
    envelope = envelope with
    {
        Body = await step(envelope.Body),
        Cursor = envelope.Cursor + 1
    };
}
